			tmp2->loop = FALSE;
			tmp2->metadata = NULL;
			tmp2->pauseTime = 0;
			tmp2->pitch = 1.0f;
			tmp2->resumeTime = 0;
			tmp2->startTime = 0;
			tmp2->stopTime = 0;
			tmp2->url.n=0; tmp2->url.p=0;
			tmp2->duration_changed = -1;
			tmp2->elapsedTime = 0;
			tmp2->isActive = FALSE;
			tmp2->isPaused = FALSE;
			tmp2->_parentResource = getInputResource();
